WITH flattened_attrs AS (SELECT id, plan, tier_limits, tier_prices, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, plan, lowest_price, LEAD(lowest_price, 1, 0) OVER w_running AS next_lowest_price, LAG(lowest_price, 1) OVER w_running AS prev_lowest_price, DENSE_RANK() OVER (PARTITION BY plan ORDER BY lowest_price NULLS FIRST) AS lowest_price_dense_rank, DENSE_RANK() OVER (PARTITION BY plan ORDER BY avg_tier_price) AS avg_tier_price_dense_rank, COUNT(avg_tier_price) OVER (PARTITION BY plan) AS plan_count_avg_tier_price FROM flattened_attrs WINDOW w_running AS (PARTITION BY plan ORDER BY lowest_price, id);
